 private static final long serialVersionUID=1L;private DefaultTableModel model=DataSet.blank(30,6);private final JTable table=new JTable(model);private final JTextArea output=new JTextArea();private final JLabel status=new JLabel("●  Ready"),counts=new JLabel();private final JTabbedPane tabs=new JTabbedPane();private final UserAccountStore accountStore;private final String username;private Path current;
