 private JPanel header(){JPanel p=new JPanel(new BorderLayout(20,0));p.setBackground(AppTheme.NAVY);p.setBorder(new EmptyBorder(18,24,18,24));JLabel mark=AppIcon.label(54);JPanel id=new JPanel(new BorderLayout());id.setOpaque(false);JLabel title=new JLabel("Statistical Solutions"),sub=new JLabel("Signed in as "+username+"  •  Data clarity. Confident decisions.");title.setForeground(AppTheme.HEADING);title.setFont(new Font(Font.SANS_SERIF,Font.BOLD,24));sub.setForeground(AppTheme.MUTED);sub.setFont(new Font(Font.SANS_SERIF,Font.PLAIN,12));id.add(title);id.add(sub,BorderLayout.SOUTH);JPanel brand=new JPanel(new BorderLayout(14,0));brand.setOpaque(false);brand.add(mark,BorderLayout.WEST);brand.add(id);JPanel actions=new JPanel(new FlowLayout(FlowLayout.RIGHT,10,3));actions.setOpaque(false);JButton open=AppTheme.button("Open Data",AppTheme.BLUE),save=AppTheme.button("Save Data",AppTheme.NAVY_2);open.addActionListener(e->openData());save.addActionListener(e->save(false));actions.add(open);actions.add(save);p.add(brand,BorderLayout.WEST);p.add(actions,BorderLayout.EAST);return p;}
